import{_ as a,o as t,c as r,a6 as i}from"./chunks/framework.B0gLQ86H.js";const u=JSON.parse('{"title":"Work with spatial indexes","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/spatial-indexes.md","filePath":"how-to/spatial-indexes.md","lastUpdated":null}'),o={name:"how-to/spatial-indexes.md"};function s(n,e,d,p,l,c){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="Work-with-spatial-indexes" tabindex="-1">Work with spatial indexes <a class="header-anchor" href="#Work-with-spatial-indexes" aria-label="Permalink to &quot;Work with spatial indexes {#Work-with-spatial-indexes}&quot;">​</a></h1><p>Use this guide when you need faster repeated spatial filtering or joins.</p><h2 id="Current-GeoDataFrames-behavior" tabindex="-1">Current GeoDataFrames behavior <a class="header-anchor" href="#Current-GeoDataFrames-behavior" aria-label="Permalink to &quot;Current GeoDataFrames behavior {#Current-GeoDataFrames-behavior}&quot;">​</a></h2><p><code>GeoDataFrames.read</code> may store geometry columns in <code>GeometryVector</code>, but GeoDataFrames does not currently expose a public API to build and query a spatial index directly on that vector.</p><p>For join workflows, <a href="https://github.com/JuliaAPlavin/FlexiJoins.jl" target="_blank" rel="noreferrer">FlexiJoins</a> performs candidate filtering with an STR tree on the right-side table before running the exact geometry predicate.</p><h2 id="Speed-up-repeated-spatial-queries" tabindex="-1">Speed up repeated spatial queries <a class="header-anchor" href="#Speed-up-repeated-spatial-queries" aria-label="Permalink to &quot;Speed up repeated spatial queries {#Speed-up-repeated-spatial-queries}&quot;">​</a></h2><p>For repeated predicate evaluation over larger datasets, use an index-oriented package and keep geometries in a table with one consistent CRS:</p><ol><li><p>Reproject both datasets to a suitable projected CRS when distance or area assumptions matter.</p></li><li><p>Build or reuse the package&#39;s index structure once.</p></li><li><p>Use the index to narrow candidates, then apply exact predicates (<code>intersects</code>, <code>within</code>, <code>contains</code>) to candidates.</p></li></ol><p>See <a href="./spatial-joins">perform a spatial join</a> for table-level join patterns and <a href="./../background/operations-and-joins">operations and joins background</a> for design rationale.</p>',9)])])}const m=a(o,[["render",s]]);export{u as __pageData,m as default};
